package org.apache.commons.math.stat.descriptive.moment;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.exception.NullArgumentException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.stat.descriptive.AbstractStorelessUnivariateStatistic;
import org.apache.commons.math.stat.descriptive.WeightedEvaluation;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Unit tests for Variance.copy(Variance, Variance)
 */
public class Variance_copy_TriageGen1Test {

    @Test
    public void testCopy_Success() {
        // Arrange
        Variance source = new Variance(true);
        source.increment(1.0);
        source.increment(2.0);
        source.increment(3.0);

        double expectedResult = source.getResult();
        boolean expectedBiasCorrected = source.isBiasCorrected();
        long expectedN = source.getN();

        Variance dest = new Variance();

        // Act
        Variance.copy(source, dest);

        // Assert
        assertEquals("Result (variance) should be copied", expectedResult, dest.getResult(), 1e-10);
        assertEquals("Bias corrected status should be copied", expectedBiasCorrected, dest.isBiasCorrected());
        assertEquals("N (count) should be copied", expectedN, dest.getN());
    }

    @Test
    public void testCopy_DifferentBiasCorrection() {
        // Arrange
        Variance source = new Variance(true);
        source.increment(10.0);

        Variance dest = new Variance(false);

        // Act
        Variance.copy(source, dest);

        // Assert
        assertTrue("Destination should now be bias corrected", dest.isBiasCorrected());
    }

    @Test(expected = NullArgumentException.class)
    public void testCopy_SourceNull() {
        // Arrange
        Variance dest = new Variance();

        // Act
        Variance.copy(null, dest);
    }

    @Test(expected = NullArgumentException.class)
    public void testCopy_DestNull() {
        // Arrange
        Variance source = new Variance();

        // Act
        Variance.copy(source, null);
    }

    @Test(expected = NullArgumentException.class)
    public void testCopy_BothNull() {
        // Act
        Variance.copy(null, null);
    }
}
